from dateutil.parser import parse
tests = ["10 h 30", "10 m 30", "10 h 30 s", "10 m 30.5", "10 h 30m 20s", "10 h 30 ",
         "1 h 30", "10 h 30.5", "10 h 30.5 s", "10 m 30.5 s", "10 s 30", "10 h 30 m 20 s"]
